import { Group, Mesh, BoxGeometry, EdgesGeometry, LineSegments, Vector3 } from 'three/webgpu';
import { LineBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Properties for animation
  const state = {
    originalY: 0,
    hoverTimeline: null,
    pressTimeline: null,
    modelLoaded: false,
    edgeVisible: false,
  };

  // Create accent edge (wireframe box) – hidden initially
  const edgeMaterial = new LineBasicNodeMaterial({ color: config.colors?.accent || '#ff2a38' });
  const edgeBox = new BoxGeometry(1, 1, 1); // will be sized after model loads
  const edgeEdges = new EdgesGeometry(edgeBox);
  const edgeLine = new LineSegments(edgeEdges, edgeMaterial);
  edgeLine.visible = false;
  group.add(edgeLine);

  // Load GLB
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;
    group.add(scene);

    // Compute bounding box to size edge
    const box = new THREE.Box3().setFromObject(scene);
    const size = box.getSize(new Vector3());
    const margin = 0.05;
    edgeBox.copy(new BoxGeometry(size.x + margin * 2, size.y + margin * 2, size.z + margin * 2));
    edgeEdges.dispose(); // re-create edges geometry with new box
    // Since we can't replace geometry on LineSegments directly, we create a new one
    const newEdgeEdges = new EdgesGeometry(edgeBox);
    edgeLine.geometry = newEdgeEdges;
    // Position edge at center of model
    const center = box.getCenter(new Vector3());
    edgeLine.position.copy(center);

    state.modelLoaded = true;
  });

  // Store original position for rise-in (assumed adapter sets position after creation)
  // We'll capture it on first pointerenter
  let initialYSet = false;

  // Event handlers
  group.userData.handlers = {
    pointerenter: () => {
      if (!initialYSet) {
        state.originalY = group.position.y;
        initialYSet = true;
      }
      // Rise-in animation
      if (state.hoverTimeline) state.hoverTimeline.kill();
      state.hoverTimeline = gsap.to(group.position, {
        y: state.originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      // Show accent edge
      edgeLine.visible = true;
      state.edgeVisible = true;
    },
    pointerleave: () => {
      // Revert rise-in
      if (state.hoverTimeline) state.hoverTimeline.kill();
      state.hoverTimeline = gsap.to(group.position, {
        y: state.originalY,
        duration: 0.7,
        ease: 'power3.out',
      });
      // Hide accent edge
      edgeLine.visible = false;
      state.edgeVisible = false;
      // Also revert press-down if still active
      if (state.pressTimeline) state.pressTimeline.kill();
      gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    pointerdown: () => {
      // Press-down scale
      if (state.pressTimeline) state.pressTimeline.kill();
      state.pressTimeline = gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    pointerup: () => {
      // Revert press-down and emit event
      if (state.pressTimeline) state.pressTimeline.kill();
      state.pressTimeline = gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.12,
        ease: 'back.out',
      });
      // Emit click event
      ctx.emit('hub-home.select');
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (state.hoverTimeline) state.hoverTimeline.kill();
    if (state.pressTimeline) state.pressTimeline.kill();
    edgeMaterial.dispose();
    edgeLine.geometry.dispose();
    // Dispose loaded model resources (optional, but good practice)
    group.children.forEach(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
